use kobo_web_document::{Limits,SupplyBudget,SnapshotState,HistoryState,InputState,FocusState,TargetState};
fn snap()->SnapshotState{SnapshotState{history:None,input:None,focus:None,target:None}}
fn run(c:&str,b:&str,l:&Limits,s:&SnapshotState)->kobo_web_document::style_tree::StyleTree{let h=format!("<!doctype html><style>{c}</style>{b}");kobo_web_document::parse_style_tree_with_state(h.as_bytes(),&[],l,None,SupplyBudget::CANONICAL,s)}
fn subject<'a>(t:&'a kobo_web_document::style_tree::StyleTree,key:&str)->&'a kobo_web_document::style_tree::StyledNode{let x=t.nodes.iter().find(|n|n.text.as_deref()==Some(key)).unwrap();&t.nodes[x.parent.unwrap()]}
const Q:&str=":is(.a,.b,.c,.d,.e)";
#[test] fn faithful_original_p_subjects_neutral_color_no_inherited_coincidence(){let h=include_str!("fixtures/is_five_oracle.html");let q=include_str!("fixtures/is_five_original1.txt").trim();let baseline=run("",h,&Limits::DEFAULT,&snap());assert!(!baseline.unsupported&&!baseline.truncated);let t=run(&format!("{q}{{color:red}}"),h,&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);for i in 0..12{let k=format!("p{i}");let yes=(1..=7).contains(&i)||i==11;let n=subject(&t,&k);assert_eq!(n.tag,"p");assert_eq!(n.style.color,if yes{0xff0000}else{0},"{k}");}for(k,w)in[("missing",0),("self",0),("nested",0xff0000),("divsubject",0xff0000)]{assert_eq!(subject(&t,k).style.color,w,"{k}");}assert!(t.nodes.iter().filter(|n|n.tag=="div").take(1).all(|n|n.style.color==0));}
#[test] fn browser_rank_max_not_sum_and_wrappers(){let t=run("",include_str!("fixtures/is_five_cascade.html"),&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);for(k,w)in[("z",0x0000ff),("strong",0xff0000),("w",0x0000ff),("v",0x0000ff),("m",0x0000ff),("h",0x0000ff)]{assert_eq!(subject(&t,k).style.color,w,"{k}");}}
#[test] fn comma_count_mixed_separate_steps_and_16_17(){let q=format!("{Q} :not(.x,.y) :has(.u,.v)");let t=run(&format!("{q}{{color:red}}"),"<div class=a><div><div><b class=u></b></div></div></div>",&Limits::DEFAULT,&snap());assert!(!t.unsupported&&!t.truncated);for(n,w)in[(16,false),(17,true)]{let t=run(&format!("{}{{color:red}}",vec![Q;n].join(",")),"<p class=a>x</p>",&Limits::DEFAULT,&snap());assert_eq!(t.unsupported,w);}for q in [":is(.a,.b,.c,.d)",":is(.a,.b,.c,.d,.e,.f)",":is(.a,.b,.c,.d,.e)[x=\"a,b\"]",":is(.a,.b,.c,.d,.e):not(.x,.y):has(.u,.v)"]{assert!(run(&format!("{q}{{color:red}}"),"<p class=a>x</p>",&Limits::DEFAULT,&snap()).unsupported);}assert!(kobo_web_document::parse_style_tree(b"<!doctype html><style>:is(.a,.b,.c,.d,.e){color:red}</style><p class=a>x</p>",&[],&Limits::DEFAULT).unsupported);}
#[test] fn global_work_partial_attributes_limits_and_independent_state_guards(){let q=":is(.a,.b,.c,.d,.e){color:red}";let b=format!("<p class='{}'>x</p>","z ".repeat(80));let t=run(q,&b,&Limits::DEFAULT,&snap());assert!(!t.truncated);let t=run(&q.repeat(100),&b.repeat(1500),&Limits{max_input_bytes:4_000_000,max_nodes:200_000,..Limits::DEFAULT},&snap());assert!(t.truncated);assert!(t.diagnostics.count(kobo_web_document::style_diagnostics::RefusalReason::MatchWork)>0);let b=format!("<p {} class=a>x</p>",(0..40).map(|i|format!("data-x{i}=a ")).collect::<String>());let t=run(q,&b,&Limits::DEFAULT,&snap());assert!(t.truncated&&t.diagnostics.dropped_attributes>0);assert!(!t.unsupported);for l in [Limits{max_input_bytes:30,..Limits::DEFAULT},Limits{max_nodes:1,..Limits::DEFAULT},Limits{max_text_bytes:0,..Limits::DEFAULT}]{let t=run(q,"<p class=a>text</p>",&l,&snap());assert!(t.truncated||t.unsupported);}
 let q=format!(".absent:focus{Q}{{color:red}}");let mut s=snap();assert!(run(&q,"<p></p>",&Limits::DEFAULT,&s).unsupported);s.history=Some(HistoryState::FreshNoHistory);s.input=Some(InputState::QuiescentCapture);assert!(run(&q,"<p></p>",&Limits::DEFAULT,&s).unsupported);s.focus=Some(FocusState::UnfocusedInitial);assert!(!run(&q,"<p></p>",&Limits::DEFAULT,&s).unsupported);assert!(run(&q,"<p autofocus></p>",&Limits::DEFAULT,&s).unsupported);assert!(run(&format!(".absent:target{Q}{{color:red}}"),"<p></p>",&Limits::DEFAULT,&s).unsupported);s.target=Some(TargetState::Fragment("x".into()));assert!(!run(&format!("p:target{Q}{{color:red}}"),"<p id=x class=a>x</p>",&Limits::DEFAULT,&s).unsupported);
}
